-- ==========================================================================
--  SAPI — complete database setup
--  GENERATED by server/scripts/build-setup.mts — do not edit by hand.
--
--  HOW TO USE
--    1. Supabase Dashboard -> SQL Editor -> New query
--    2. Paste this entire file
--    3. Run it
--
--  Everything runs inside one transaction: if any statement fails, the
--  database rolls back to its previous state and nothing is left half-built.
--
--  Safe to re-run. Reference tables are upserted; transactional rows are
--  only inserted when absent, so in-progress work is never clobbered.
--
--  Regenerate after changing anything under src/app/data/:
--      cd server && npm run seed:sql && npm run setup:sql
-- ==========================================================================

begin;
-- ==========================================================================
--  0001_schema.sql — enums, tables, generated columns, triggers
-- ==========================================================================

-- ============================================================================
--  Southwind Automotive Parts Inc. (SAPI)
--  Integrated Inventory Reconciliation, Auditing & Decision Support System
--
--  Migration 0001 — schema
--
--  Run order in the Supabase SQL Editor:  0001 -> 0002 -> 0003 -> 0004 -> seed.sql
--  (Or paste supabase/setup-all.sql once — it is these files in that order.)
--
--  Design notes
--  ------------
--  * Every identifier that already exists in the client domain model is kept
--    verbatim as a natural key (branch id, SKU, ticket id) so the React layer
--    needs no translation table.
--  * `stock_records` is the fact table: one row per (SKU, branch) position.
--    Derived figures (status, value, shortfall) are NOT stored — they live in
--    the `v_stock_enriched` view so they can never drift out of sync.
--  * `variance` and `variance_value` on discrepancies ARE stored, as generated
--    columns, because the approval workflow audits them and they must be
--    immutable evidence rather than a recomputed value.
-- ============================================================================

-- No `create extension` is needed. This schema deliberately depends on nothing
-- beyond core Postgres: primary keys are natural keys (branch id, SKU, ticket
-- id) or supplied by Supabase Auth, so there is no `gen_random_uuid()` call and
-- no `pgcrypto`. An earlier revision ran `create extension if not exists
-- "pgcrypto"`; nothing used it, and because the whole script is one transaction
-- a failure there would have rolled back the entire migration, so it was
-- removed rather than left in as a single point of failure.

-- ─────────────────────────────────────────────────────────────────────────────
--  Enumerated types
-- ─────────────────────────────────────────────────────────────────────────────
--
-- Every type is created inside its own guarded block. A bare `create type`
-- raises `duplicate_object` on the second run, which aborts the surrounding
-- transaction and rolls the whole migration back — the exact opposite of what a
-- file documented as "safe to re-run" should do. Guarding here, together with
-- `if not exists` on the tables and indexes below, is what actually delivers
-- that promise.

do $enums$
begin
  -- The three user-facing roles requested for the system. A single `profiles`
  -- row per auth user carries exactly one of these.
  begin
    create type public.user_role as enum ('management', 'warehouse', 'sales');
  exception when duplicate_object then null; end;

  begin
    create type public.part_category as enum (
      'Engine Parts', 'Brakes', 'Electrical', 'Suspension',
      'Filters', 'Exhaust', 'Drivetrain', 'Body Parts'
    );
  exception when duplicate_object then null; end;

  -- ABC classification drives how heavily a position is weighted in the
  -- targeted cycle-count score (Objective 1).
  begin
    create type public.abc_class as enum ('A', 'B', 'C');
  exception when duplicate_object then null; end;

  begin
    create type public.cycle_priority as enum ('Critical', 'High', 'Medium', 'Low');
  exception when duplicate_object then null; end;

  begin
    create type public.cycle_task_status as enum (
      'Pending', 'Sheet Printed', 'Counted', 'Reconciled'
    );
  exception when duplicate_object then null; end;

  -- Objective 2 — a count that does not match locks the record until a
  -- management user approves or rejects it.
  begin
    create type public.discrepancy_status as enum (
      'Locked', 'Under Review', 'Approved', 'Rejected'
    );
  exception when duplicate_object then null; end;

  begin
    create type public.root_cause as enum (
      'Miscount', 'Unrecorded Transfer', 'Damaged Goods', 'Misplaced Item',
      'Supplier Short-Ship', 'Encoding Error', 'Theft / Shrinkage'
    );
  exception when duplicate_object then null; end;

  begin
    create type public.transfer_status as enum (
      'Pending', 'Approved', 'In Transit', 'Completed', 'Rejected'
    );
  exception when duplicate_object then null; end;

  begin
    create type public.po_status as enum (
      'Draft', 'Submitted', 'Confirmed', 'Partially Received', 'Completed', 'Cancelled'
    );
  exception when duplicate_object then null; end;

  begin
    create type public.supplier_status as enum ('Active', 'Inactive');
  exception when duplicate_object then null; end;

  begin
    create type public.account_status as enum ('Active', 'Suspended');
  exception when duplicate_object then null; end;
end
$enums$;

-- ─────────────────────────────────────────────────────────────────────────────
--  Reference data
-- ─────────────────────────────────────────────────────────────────────────────

-- The eight branches named in the proposal. QC is the main warehouse.
create table if not exists public.branches (
  id          text primary key,
  name        text not null,
  short_name  text not null,
  region      text not null,
  manager     text not null,
  address     text not null,
  phone       text not null,
  is_main     boolean not null default false,
  created_at  timestamptz not null default now()
);

create table if not exists public.parts (
  sku            text primary key,
  name           text not null,
  category       public.part_category not null,
  brand          text not null,
  unit_cost      numeric(12, 2) not null check (unit_cost >= 0),
  reorder_point  integer not null check (reorder_point >= 0),
  abc_class      public.abc_class not null,
  created_at     timestamptz not null default now()
);

create index if not exists parts_category_idx on public.parts (category);
create index if not exists parts_abc_class_idx on public.parts (abc_class);

create table if not exists public.suppliers (
  id              integer primary key,
  name            text not null,
  categories      text not null,
  phone           text not null,
  email           text not null,
  lead_time_days  integer not null check (lead_time_days >= 0),
  rating          numeric(2, 1) not null check (rating between 0 and 5),
  active_pos      integer not null default 0 check (active_pos >= 0),
  status          public.supplier_status not null default 'Active',
  created_at      timestamptz not null default now()
);

-- Single-row configuration table backing the Settings screen.
create table if not exists public.company_settings (
  id             boolean primary key default true check (id),
  name           text not null,
  short_name     text not null,
  abbr           text not null,
  system_name    text not null,
  hq             text not null,
  phone          text not null,
  email          text not null,
  website        text not null,
  branch_count   integer not null default 8,
  no_phone_policy text not null,
  updated_at     timestamptz not null default now()
);

-- ─────────────────────────────────────────────────────────────────────────────
--  Users
-- ─────────────────────────────────────────────────────────────────────────────

-- Application profile, one-to-one with auth.users. `role` and `branch_id` are
-- the two facts every RLS policy keys off.
create table if not exists public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  email       text not null,
  full_name   text not null,
  role        public.user_role not null default 'sales',
  branch_id   text references public.branches (id) on delete set null,
  job_title   text,
  status      public.account_status not null default 'Active',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index if not exists profiles_role_idx on public.profiles (role);
create index if not exists profiles_branch_idx on public.profiles (branch_id);

-- ─────────────────────────────────────────────────────────────────────────────
--  Stock — the fact table
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.stock_records (
  sku                   text not null references public.parts (sku) on delete cascade,
  branch_id             text not null references public.branches (id) on delete cascade,
  on_hand               integer not null default 0 check (on_hand >= 0),
  bin_location          text not null,
  days_since_movement   integer not null default 0 check (days_since_movement >= 0),
  days_since_count      integer not null default 0 check (days_since_count >= 0),
  days_since_transfer   integer check (days_since_transfer is null or days_since_transfer >= 0),
  -- Set by the approval workflow: while a discrepancy ticket is open against
  -- this position, the record is frozen and cannot be recounted.
  locked_by_discrepancy text,
  updated_at            timestamptz not null default now(),
  primary key (sku, branch_id)
);

create index if not exists stock_records_branch_idx on public.stock_records (branch_id);
create index if not exists stock_records_staleness_idx on public.stock_records (days_since_count desc);
create index if not exists stock_records_movement_idx on public.stock_records (days_since_movement desc);

-- ─────────────────────────────────────────────────────────────────────────────
--  Objective 1 — Targeted cycle counting
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.cycle_tasks (
  id                   text primary key,
  sku                  text not null references public.parts (sku) on delete cascade,
  branch_id            text not null references public.branches (id) on delete cascade,
  bin_location         text not null,
  priority             public.cycle_priority not null,
  score                numeric(6, 1) not null check (score >= 0),
  days_since_count     integer not null,
  days_since_transfer  integer,
  abc_class            public.abc_class not null,
  reason               text not null,
  status               public.cycle_task_status not null default 'Pending',
  assigned_to          text,
  generated_at         timestamptz not null default now(),
  printed_at           timestamptz,
  counted_at           timestamptz,
  reconciled_at        timestamptz,
  created_by           uuid references public.profiles (id) on delete set null,
  updated_at           timestamptz not null default now()
);

create index if not exists cycle_tasks_branch_idx on public.cycle_tasks (branch_id);
create index if not exists cycle_tasks_status_idx on public.cycle_tasks (status);
create index if not exists cycle_tasks_priority_idx on public.cycle_tasks (priority);
-- One live task per position; regenerating replaces the queue.
create unique index if not exists cycle_tasks_position_key
  on public.cycle_tasks (sku, branch_id)
  where status <> 'Reconciled';

-- ─────────────────────────────────────────────────────────────────────────────
--  Objective 2 — Discrepancy approval workflow
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.discrepancies (
  id             text primary key,
  sku            text not null references public.parts (sku) on delete cascade,
  branch_id      text not null references public.branches (id) on delete cascade,
  bin_location   text not null,
  system_qty     integer not null,
  counted_qty    integer not null,
  variance       integer generated always as (counted_qty - system_qty) stored,
  unit_cost      numeric(12, 2) not null check (unit_cost >= 0),
  variance_value numeric(14, 2) generated always as
                   (abs(counted_qty - system_qty) * unit_cost) stored,
  root_cause     public.root_cause,
  status         public.discrepancy_status not null default 'Locked',
  notes          text not null default '',
  raised_by      text not null,
  raised_by_id   uuid references public.profiles (id) on delete set null,
  raised_at      timestamptz not null default now(),
  reviewed_by    text,
  reviewed_by_id uuid references public.profiles (id) on delete set null,
  reviewed_at    timestamptz,
  -- Only an approval carries a root cause; the workflow enforces it here too.
  constraint discrepancy_review_coherent check (
    (status = 'Approved' and root_cause is not null and reviewed_at is not null)
    or (status in ('Locked', 'Under Review'))
    or (status = 'Rejected' and reviewed_at is not null)
  )
);

create index if not exists discrepancies_branch_idx on public.discrepancies (branch_id);
create index if not exists discrepancies_status_idx on public.discrepancies (status);
create index if not exists discrepancies_raised_at_idx on public.discrepancies (raised_at desc);
create index if not exists discrepancies_root_cause_idx on public.discrepancies (root_cause);

-- ─────────────────────────────────────────────────────────────────────────────
--  Objective 4 — Dead-stock matchmaker + supply chain
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.transfers (
  id             text primary key,
  sku            text not null references public.parts (sku) on delete cascade,
  part_name      text not null,
  from_branch_id text not null references public.branches (id) on delete cascade,
  to_branch_id   text not null references public.branches (id) on delete cascade,
  qty            integer not null check (qty > 0),
  requested_by   text not null,
  requested_by_id uuid references public.profiles (id) on delete set null,
  transfer_date  date not null default current_date,
  status         public.transfer_status not null default 'Pending',
  -- True when the row originated from an accepted matchmaker suggestion.
  auto_suggested boolean not null default false,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint transfers_distinct_branches check (from_branch_id <> to_branch_id)
);

create index if not exists transfers_status_idx on public.transfers (status);
create index if not exists transfers_from_idx on public.transfers (from_branch_id);
create index if not exists transfers_to_idx on public.transfers (to_branch_id);
create index if not exists transfers_date_idx on public.transfers (transfer_date desc);

create table if not exists public.purchase_orders (
  id            text primary key,
  supplier      text not null,
  items         integer not null check (items >= 0),
  total         numeric(14, 2) not null check (total >= 0),
  order_date    date not null,
  delivery_date date not null,
  status        public.po_status not null default 'Draft',
  created_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index if not exists purchase_orders_status_idx on public.purchase_orders (status);
create index if not exists purchase_orders_order_date_idx on public.purchase_orders (order_date desc);

-- ─────────────────────────────────────────────────────────────────────────────
--  Triggers
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- `create trigger` has no `if not exists` form, so each is dropped first. The
-- drop is a no-op on a first run and makes re-runs safe.
drop trigger if exists profiles_touch on public.profiles;
create trigger profiles_touch        before update on public.profiles
  for each row execute function public.touch_updated_at();
drop trigger if exists stock_records_touch on public.stock_records;
create trigger stock_records_touch   before update on public.stock_records
  for each row execute function public.touch_updated_at();
drop trigger if exists cycle_tasks_touch on public.cycle_tasks;
create trigger cycle_tasks_touch     before update on public.cycle_tasks
  for each row execute function public.touch_updated_at();
drop trigger if exists transfers_touch on public.transfers;
create trigger transfers_touch       before update on public.transfers
  for each row execute function public.touch_updated_at();
drop trigger if exists purchase_orders_touch on public.purchase_orders;
create trigger purchase_orders_touch before update on public.purchase_orders
  for each row execute function public.touch_updated_at();

-- Mirror every new auth user into `profiles`. Role and branch are read from the
-- sign-up metadata, defaulting to the least-privileged role (sales) so a
-- mis-provisioned account can never self-escalate.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role   public.user_role := 'sales';
  v_branch text;
  v_name   text;
  v_title  text;
begin
  if (new.raw_user_meta_data ? 'role') then
    begin
      v_role := (new.raw_user_meta_data ->> 'role')::public.user_role;
    exception when invalid_text_representation then
      v_role := 'sales';
    end;
  end if;

  v_branch := new.raw_user_meta_data ->> 'branch_id';
  if v_branch is not null and not exists (select 1 from public.branches where id = v_branch) then
    v_branch := null;
  end if;

  v_name  := coalesce(nullif(new.raw_user_meta_data ->> 'full_name', ''), split_part(new.email, '@', 1));
  v_title := new.raw_user_meta_data ->> 'job_title';

  insert into public.profiles (id, email, full_name, role, branch_id, job_title)
  values (new.id, new.email, v_name, v_role, v_branch, v_title)
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ==========================================================================
--  0002_rls.sql — helper functions, escalation guard, RLS policies
-- ==========================================================================

-- ============================================================================
--  SAPI — Migration 0002 — Row Level Security
--
--  The three roles and what they may do (proposal-faithful):
--
--    management  Full oversight. Approves or rejects discrepancy tickets,
--                generates and assigns cycle-count work, manages parts,
--                suppliers and purchase orders.
--    warehouse   Encodes physical counts, prints blind-count sheets, raises
--                discrepancy tickets for its own branch, and executes
--                inter-branch transfers.
--    sales       Read-only visibility of stock availability across all eight
--                branches, plus the ability to request a transfer.
--
--  All three roles may SELECT across branches: the whole point of the system
--  is that a sales officer in Dipolog can see what Cebu has on the shelf.
--  Writes are where the roles diverge.
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
--  Role helpers
--
--  These are SECURITY DEFINER on purpose. A policy on `profiles` that queried
--  `profiles` would recurse; running the lookup as the owner sidesteps that and
--  also lets the same helpers be reused inside the self-escalation trigger.
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.auth_role()
returns public.user_role
language sql
stable
security definer
set search_path = public
as $$
  select p.role from public.profiles p where p.id = auth.uid();
$$;

create or replace function public.auth_branch_id()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select p.branch_id from public.profiles p where p.id = auth.uid();
$$;

create or replace function public.is_management()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role = 'management' and p.status = 'Active'
  );
$$;

create or replace function public.is_warehouse()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role = 'warehouse' and p.status = 'Active'
  );
$$;

create or replace function public.is_sales()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role = 'sales' and p.status = 'Active'
  );
$$;

/** Any signed-in user with a live profile. */
create or replace function public.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.status = 'Active'
  );
$$;

-- ─────────────────────────────────────────────────────────────────────────────
--  Privilege-escalation guard
--
--  RLS `with check` cannot compare against the previous row, so a user who is
--  allowed to edit their own profile could otherwise promote themselves to
--  management. This trigger closes that hole: only management (or the service
--  role, which bypasses RLS entirely) may change `role`, `branch_id` or
--  `status`.
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.prevent_profile_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- `auth.uid() is null` means the service role / a direct SQL session
  -- (the seed script). Those are trusted.
  if auth.uid() is null or public.is_management() then
    return new;
  end if;

  if new.role is distinct from old.role
     or new.branch_id is distinct from old.branch_id
     or new.status is distinct from old.status then
    raise exception
      'Only management may change role, branch or account status'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$$;

drop trigger if exists profiles_guard_escalation on public.profiles;
create trigger profiles_guard_escalation
  before update on public.profiles
  for each row execute function public.prevent_profile_escalation();

-- ─────────────────────────────────────────────────────────────────────────────
--  Enable RLS everywhere
-- ─────────────────────────────────────────────────────────────────────────────

alter table public.branches         enable row level security;
alter table public.parts            enable row level security;
alter table public.suppliers        enable row level security;
alter table public.company_settings enable row level security;
alter table public.profiles         enable row level security;
alter table public.stock_records    enable row level security;
alter table public.cycle_tasks      enable row level security;
alter table public.discrepancies    enable row level security;
alter table public.transfers        enable row level security;
alter table public.purchase_orders  enable row level security;

-- ─────────────────────────────────────────────────────────────────────────────
--  branches — readable by everyone signed in, curated by management
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists branches_select on public.branches;

create policy branches_select on public.branches
  for select to authenticated using (public.is_active_user());

drop policy if exists branches_insert on public.branches;

create policy branches_insert on public.branches
  for insert to authenticated with check (public.is_management());

drop policy if exists branches_update on public.branches;

create policy branches_update on public.branches
  for update to authenticated
  using (public.is_management()) with check (public.is_management());

drop policy if exists branches_delete on public.branches;

create policy branches_delete on public.branches
  for delete to authenticated using (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  parts — catalogue is readable by all, maintained by management
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists parts_select on public.parts;

create policy parts_select on public.parts
  for select to authenticated using (public.is_active_user());

drop policy if exists parts_insert on public.parts;

create policy parts_insert on public.parts
  for insert to authenticated with check (public.is_management());

drop policy if exists parts_update on public.parts;

create policy parts_update on public.parts
  for update to authenticated
  using (public.is_management()) with check (public.is_management());

drop policy if exists parts_delete on public.parts;

create policy parts_delete on public.parts
  for delete to authenticated using (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  suppliers
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists suppliers_select on public.suppliers;

create policy suppliers_select on public.suppliers
  for select to authenticated using (public.is_active_user());

drop policy if exists suppliers_write on public.suppliers;

create policy suppliers_write on public.suppliers
  for all to authenticated
  using (public.is_management()) with check (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  company_settings — one row, management edits
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists company_settings_select on public.company_settings;

create policy company_settings_select on public.company_settings
  for select to authenticated using (public.is_active_user());

drop policy if exists company_settings_update on public.company_settings;

create policy company_settings_update on public.company_settings
  for update to authenticated
  using (public.is_management()) with check (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  profiles
--
--  Everyone signed in may read the directory — the UI needs to resolve
--  "assigned to" and "reviewed by" display names. Only management may write
--  arbitrary rows; everyone else may edit their own name and job title, and
--  the trigger above stops them touching role / branch / status.
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists profiles_select on public.profiles;

create policy profiles_select on public.profiles
  for select to authenticated using (public.is_active_user());

drop policy if exists profiles_update_self on public.profiles;

create policy profiles_update_self on public.profiles
  for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

drop policy if exists profiles_manage on public.profiles;

create policy profiles_manage on public.profiles
  for all to authenticated
  using (public.is_management()) with check (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  stock_records — the fact table
--
--  Read: every signed-in role, all branches (this is the cross-branch
--        availability the sales desk depends on).
--  Write: warehouse (reconcile a counted position) and management (apply an
--         approved variance). Sales never writes stock.
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists stock_select on public.stock_records;

create policy stock_select on public.stock_records
  for select to authenticated using (public.is_active_user());

drop policy if exists stock_update on public.stock_records;

create policy stock_update on public.stock_records
  for update to authenticated
  using (public.is_management() or public.is_warehouse())
  with check (public.is_management() or public.is_warehouse());

drop policy if exists stock_insert on public.stock_records;

create policy stock_insert on public.stock_records
  for insert to authenticated with check (public.is_management());

drop policy if exists stock_delete on public.stock_records;

create policy stock_delete on public.stock_records
  for delete to authenticated using (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  cycle_tasks — Objective 1
--
--  Management generates the queue for any branch and may reassign work.
--  Warehouse staff work the queue for their own branch only.
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists cycle_tasks_select on public.cycle_tasks;

create policy cycle_tasks_select on public.cycle_tasks
  for select to authenticated using (public.is_active_user());

drop policy if exists cycle_tasks_insert on public.cycle_tasks;

create policy cycle_tasks_insert on public.cycle_tasks
  for insert to authenticated
  with check (
    public.is_management()
    or (public.is_warehouse() and branch_id = public.auth_branch_id())
  );

drop policy if exists cycle_tasks_update on public.cycle_tasks;

create policy cycle_tasks_update on public.cycle_tasks
  for update to authenticated
  using (
    public.is_management()
    or (public.is_warehouse() and branch_id = public.auth_branch_id())
  )
  with check (
    public.is_management()
    or (public.is_warehouse() and branch_id = public.auth_branch_id())
  );

drop policy if exists cycle_tasks_delete on public.cycle_tasks;

create policy cycle_tasks_delete on public.cycle_tasks
  for delete to authenticated using (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  discrepancies — Objective 2
--
--  Warehouse raises tickets for its own branch. ONLY management decides.
--  There is deliberately no update policy for warehouse or sales: once a
--  ticket is Locked it stays Locked until a manager rules on it, which is the
--  control the proposal promises.
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists discrepancies_select on public.discrepancies;

create policy discrepancies_select on public.discrepancies
  for select to authenticated using (public.is_active_user());

drop policy if exists discrepancies_insert on public.discrepancies;

create policy discrepancies_insert on public.discrepancies
  for insert to authenticated
  with check (
    public.is_management()
    or (
      public.is_warehouse()
      and branch_id = public.auth_branch_id()
      and raised_by_id = auth.uid()
      and status in ('Locked', 'Under Review')
    )
  );

drop policy if exists discrepancies_update on public.discrepancies;

create policy discrepancies_update on public.discrepancies
  for update to authenticated
  using (public.is_management()) with check (public.is_management());

drop policy if exists discrepancies_delete on public.discrepancies;

create policy discrepancies_delete on public.discrepancies
  for delete to authenticated using (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  transfers — Objective 4 output
--
--  Sales may REQUEST a transfer (the "sales staff can flag a shortage" path).
--  Warehouse and management execute and progress it.
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists transfers_select on public.transfers;

create policy transfers_select on public.transfers
  for select to authenticated using (public.is_active_user());

drop policy if exists transfers_insert on public.transfers;

create policy transfers_insert on public.transfers
  for insert to authenticated
  with check (
    public.is_management()
    or public.is_warehouse()
    or (public.is_sales() and requested_by_id = auth.uid() and status = 'Pending')
  );

drop policy if exists transfers_update on public.transfers;

create policy transfers_update on public.transfers
  for update to authenticated
  using (public.is_management() or public.is_warehouse())
  with check (public.is_management() or public.is_warehouse());

drop policy if exists transfers_delete on public.transfers;

create policy transfers_delete on public.transfers
  for delete to authenticated using (public.is_management());

-- ─────────────────────────────────────────────────────────────────────────────
--  purchase_orders — procurement is a management function
-- ─────────────────────────────────────────────────────────────────────────────

drop policy if exists purchase_orders_select on public.purchase_orders;

create policy purchase_orders_select on public.purchase_orders
  for select to authenticated using (public.is_active_user());

drop policy if exists purchase_orders_insert on public.purchase_orders;

create policy purchase_orders_insert on public.purchase_orders
  for insert to authenticated with check (public.is_management());

drop policy if exists purchase_orders_update on public.purchase_orders;

create policy purchase_orders_update on public.purchase_orders
  for update to authenticated
  using (public.is_management()) with check (public.is_management());

drop policy if exists purchase_orders_delete on public.purchase_orders;

create policy purchase_orders_delete on public.purchase_orders
  for delete to authenticated using (public.is_management());

-- ==========================================================================
--  0003_analytics.sql — security_invoker views and RPC functions
-- ==========================================================================

-- ============================================================================
--  SAPI — Migration 0003 — Derived views and analytics
--
--  The algorithmic work (cycle-count scoring, dead-stock matching) lives in the
--  Express service tier because it is business logic that deserves unit tests.
--  Aggregation, by contrast, is what Postgres is for — so every roll-up the
--  dashboard and the analytics page need is expressed here as a view or an RPC
--  and computed in the database.
--
--  Every view is declared `security_invoker = true`. Without that flag a view
--  runs as its owner and would silently bypass the RLS policies from 0002.
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
--  v_stock_enriched — the single source of truth for a stock position
--
--  Mirrors the derived fields on the client's `BranchStock` type exactly:
--    status        Out of Stock when on_hand <= 0, Low Stock below the
--                  reorder point, otherwise In Stock
--    shortfall     how many units below the reorder point
--    value         on_hand x unit_cost
--    is_dead_stock no movement for 90+ days while still holding stock
-- ─────────────────────────────────────────────────────────────────────────────

create or replace view public.v_stock_enriched
with (security_invoker = true)
as
select
  s.sku,
  s.branch_id,
  s.on_hand,
  s.bin_location,
  s.days_since_movement,
  s.days_since_count,
  s.days_since_transfer,
  s.locked_by_discrepancy,
  p.name            as part_name,
  p.category,
  p.brand,
  p.unit_cost,
  p.reorder_point,
  p.abc_class,
  b.name            as branch_name,
  b.short_name      as branch_short_name,
  b.region          as branch_region,
  b.manager         as branch_manager,
  case
    when s.on_hand <= 0                 then 'Out of Stock'
    when s.on_hand <  p.reorder_point   then 'Low Stock'
    else                                     'In Stock'
  end                                 as status,
  greatest(0, p.reorder_point - s.on_hand)          as shortfall,
  (s.on_hand * p.unit_cost)::numeric(14, 2)         as value,
  (s.days_since_movement >= 90 and s.on_hand > 0)   as is_dead_stock
from public.stock_records s
join public.parts    p on p.sku = s.sku
join public.branches b on b.id  = s.branch_id;

comment on view public.v_stock_enriched is
  'Stock positions joined with part and branch detail plus every derived field the client renders.';

-- ─────────────────────────────────────────────────────────────────────────────
--  v_branch_summary — per-branch roll-up used by the dashboard table
-- ─────────────────────────────────────────────────────────────────────────────

create or replace view public.v_branch_summary
with (security_invoker = true)
as
select
  v.branch_id,
  v.branch_name,
  v.branch_short_name,
  v.branch_region,
  v.branch_manager,
  count(*)::integer                                            as positions,
  coalesce(sum(v.on_hand), 0)::integer                          as units,
  coalesce(sum(v.value), 0)::numeric(16, 2)                     as value,
  count(*) filter (where v.status = 'Low Stock')::integer       as low_stock,
  count(*) filter (where v.status = 'Out of Stock')::integer    as out_of_stock,
  count(*) filter (where v.is_dead_stock)::integer              as dead_stock,
  count(*) filter (where v.on_hand >= v.reorder_point)::integer as healthy,
  round(
    100.0 * count(*) filter (where v.on_hand >= v.reorder_point) / nullif(count(*), 0),
    1
  )                                                             as health_rate
from public.v_stock_enriched v
group by
  v.branch_id, v.branch_name, v.branch_short_name, v.branch_region, v.branch_manager;

-- ─────────────────────────────────────────────────────────────────────────────
--  v_category_summary — per-category roll-up used by the inventory page
-- ─────────────────────────────────────────────────────────────────────────────

create or replace view public.v_category_summary
with (security_invoker = true)
as
select
  v.category,
  count(distinct v.sku)::integer                                as skus,
  count(*)::integer                                             as positions,
  coalesce(sum(v.on_hand), 0)::integer                          as units,
  coalesce(sum(v.value), 0)::numeric(16, 2)                     as value,
  count(*) filter (where v.status <> 'In Stock')::integer       as attention,
  count(*) filter (where v.is_dead_stock)::integer              as dead_stock
from public.v_stock_enriched v
group by v.category;

-- ─────────────────────────────────────────────────────────────────────────────
--  v_discrepancy_enriched — tickets with the names the UI needs
-- ─────────────────────────────────────────────────────────────────────────────

create or replace view public.v_discrepancy_enriched
with (security_invoker = true)
as
select
  d.*,
  p.name     as part_name,
  p.category,
  b.name     as branch_name,
  b.short_name as branch_short_name,
  case
    when d.status in ('Locked', 'Under Review') then true
    else false
  end        as is_open
from public.discrepancies d
join public.parts    p on p.sku = d.sku
join public.branches b on b.id  = d.branch_id;

-- ─────────────────────────────────────────────────────────────────────────────
--  rpc_dashboard_kpis — every headline number in one round trip
--
--  Two accuracy measures are reported deliberately separately. "Count accuracy"
--  is what the capstone is graded on: the share of stock positions with no
--  discrepancy ticket against them. "Stock health" is a level metric: the share
--  of positions sitting at or above their reorder point. Blending them, as the
--  original prototype did, produces a number that means nothing.
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.rpc_dashboard_kpis()
returns table (
  total_positions      integer,
  total_units          integer,
  total_value          numeric,
  dead_stock_count     integer,
  dead_stock_value     numeric,
  low_stock_count      integer,
  low_stock_value      numeric,
  out_of_stock_count   integer,
  count_accuracy       numeric,
  stock_health         numeric,
  open_discrepancies   integer,
  locked_value         numeric,
  total_variance_cost  numeric,
  resolved_this_month  integer,
  pending_transfers    integer,
  in_transit_transfers integer,
  open_pos             integer,
  po_spend_total       numeric,
  sku_count            integer,
  branch_count         integer
)
language sql
stable
set search_path = public
as $$
  with stock as (
    select * from public.v_stock_enriched
  ),
  ticket as (
    select * from public.discrepancies
  )
  select
    (select count(*) from stock)::integer,
    (select coalesce(sum(on_hand), 0) from stock)::integer,
    (select coalesce(sum(value), 0) from stock)::numeric,
    (select count(*) from stock where is_dead_stock)::integer,
    (select coalesce(sum(value), 0) from stock where is_dead_stock)::numeric,
    (select count(*) from stock where status = 'Low Stock')::integer,
    (select coalesce(sum(value), 0) from stock where status = 'Low Stock')::numeric,
    (select count(*) from stock where status = 'Out of Stock')::integer,

    -- Count accuracy: positions with a clean count record.
    (
      select round(
        100.0 * count(*) filter (
          where not exists (
            select 1 from ticket t
            where t.sku = s.sku and t.branch_id = s.branch_id
          )
        ) / nullif(count(*), 0),
        1
      )
      from stock s
    ),

    -- Stock health: positions at or above their reorder point.
    (
      select round(
        100.0 * count(*) filter (where on_hand >= reorder_point) / nullif(count(*), 0),
        1
      )
      from stock
    ),

    (select count(*) from ticket where status in ('Locked', 'Under Review'))::integer,
    (select coalesce(sum(variance_value), 0) from ticket
      where status in ('Locked', 'Under Review'))::numeric,
    (select coalesce(sum(variance_value), 0) from ticket)::numeric,
    (select count(*) from ticket
      where status in ('Approved', 'Rejected')
        and reviewed_at >= date_trunc('month', now()))::integer,

    (select count(*) from public.transfers where status = 'Pending')::integer,
    (select count(*) from public.transfers where status = 'In Transit')::integer,

    (select count(*) from public.purchase_orders
      where status in ('Submitted', 'Confirmed', 'Partially Received'))::integer,
    (select coalesce(sum(total), 0) from public.purchase_orders)::numeric,

    (select count(distinct sku) from stock)::integer,
    (select count(*) from public.branches)::integer;
$$;

-- ─────────────────────────────────────────────────────────────────────────────
--  rpc_discrepancy_analytics — Objective 3
--
--  Returns the three breakdowns the analytics page charts, as one JSON payload:
--  by month, by branch, and by root cause.
--
--  The monthly roll-up distinguishes three things, and conflating them is what
--  makes a discrepancy chart useless:
--
--    opened    tickets raised during the month
--    resolved  tickets DECIDED during the month (keyed on reviewed_at, not
--              raised_at). Keying resolution on the raise date counts every
--              already-decided ticket as resolved in the month it was raised,
--              which makes "Opened" and "Resolved" identical and hides the
--              backlog entirely.
--    backlog   tickets raised on or before the month that were still
--              undecided at its close
--
--  Months are the union of raise months and review months, so a month in which
--  the team only cleared a backlog still appears on the axis.
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.rpc_discrepancy_analytics()
returns jsonb
language sql
stable
set search_path = public
as $$
  with ticket as (
    select * from public.discrepancies
  ),
  months as (
    select date_trunc('month', raised_at) as month from ticket
    union
    select date_trunc('month', reviewed_at) from ticket where reviewed_at is not null
  ),
  by_month as (
    select
      to_char(m.month, 'Mon')  as month,
      m.month                  as sort_key,
      count(t.id) filter (
        where date_trunc('month', t.raised_at) = m.month
      )::integer               as opened,
      count(t.id) filter (
        where date_trunc('month', t.reviewed_at) = m.month
      )::integer               as resolved,
      count(t.id) filter (
        where date_trunc('month', t.raised_at) <= m.month
          and (t.reviewed_at is null or date_trunc('month', t.reviewed_at) > m.month)
      )::integer               as backlog,
      coalesce(sum(t.variance_value) filter (
        where date_trunc('month', t.raised_at) = m.month
      ), 0)::numeric           as cost
    from months m
    left join ticket t on true
    group by m.month
    order by m.month
  ),
  by_branch as (
    select
      b.id                       as branch_id,
      b.short_name               as short_name,
      count(d.id)::integer       as discrepancies,
      coalesce(sum(d.variance_value), 0)::numeric as cost,
      count(d.id) filter (where d.status = 'Approved')::integer as approved,
      count(d.id) filter (where d.status = 'Rejected')::integer as rejected,
      count(d.id) filter (where d.status in ('Locked', 'Under Review'))::integer as open,
      (
        select round(
          100.0 * count(*) filter (
            where not exists (
              select 1 from ticket t2
              where t2.sku = s.sku and t2.branch_id = b.id
            )
          ) / nullif(count(*), 0),
          1
        )
        from public.v_stock_enriched s
        where s.branch_id = b.id
      )                          as accuracy_rate
    from public.branches b
    left join ticket d on d.branch_id = b.id
    group by b.id, b.short_name
    order by count(d.id) desc
  ),
  by_cause as (
    select
      rc.cause::text             as cause,
      count(t.id)::integer       as count,
      coalesce(sum(t.variance_value), 0)::numeric as cost
    from unnest(enum_range(null::public.root_cause)) as rc(cause)
    left join ticket t on t.root_cause = rc.cause and t.status = 'Approved'
    group by rc.cause
    order by count(t.id) desc
  )
  select jsonb_build_object(
    -- Built key by key rather than with to_jsonb(x) so `sort_key`, which exists
    -- only to order the aggregation, does not leak into the payload the client
    -- deserialises into DiscrepancyByMonth.
    'byMonth',  coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'month',    x.month,
          'opened',   x.opened,
          'resolved', x.resolved,
          'backlog',  x.backlog,
          'cost',     x.cost
        ) order by x.sort_key
      )
      from by_month x
    ), '[]'::jsonb),
    'byBranch', coalesce((select jsonb_agg(to_jsonb(y)) from by_branch y), '[]'::jsonb),
    'byCause',  coalesce((select jsonb_agg(to_jsonb(z)) from by_cause z), '[]'::jsonb)
  );
$$;

-- ─────────────────────────────────────────────────────────────────────────────
--  rpc_cycle_summary — Objective 1 progress
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.rpc_cycle_summary()
returns table (
  total_tasks     integer,
  pending         integer,
  sheet_printed   integer,
  counted         integer,
  reconciled      integer,
  critical        integer,
  high            integer,
  medium          integer,
  low             integer,
  completion_rate numeric
)
language sql
stable
set search_path = public
as $$
  select
    count(*)::integer,
    count(*) filter (where status = 'Pending')::integer,
    count(*) filter (where status = 'Sheet Printed')::integer,
    count(*) filter (where status = 'Counted')::integer,
    count(*) filter (where status = 'Reconciled')::integer,
    count(*) filter (where priority = 'Critical')::integer,
    count(*) filter (where priority = 'High')::integer,
    count(*) filter (where priority = 'Medium')::integer,
    count(*) filter (where priority = 'Low')::integer,
    round(
      100.0 * count(*) filter (where status = 'Reconciled') / nullif(count(*), 0),
      1
    )
  from public.cycle_tasks;
$$;

-- ==========================================================================
--  0004_matchmaker.sql — suggestion dismissal ledger
-- ==========================================================================

-- ============================================================================
--  SAPI — Migration 0004 — Matchmaker decisions
--
--  Objective 4 proposes transfers. Two things then need to be remembered:
--
--    * Accepting a suggestion creates a `transfers` row (already covered by
--      0001), and the suggestion is suppressed from then on because the
--      matchmaker ignores pairs that already have a live transfer.
--    * Dismissing a suggestion has no transfer to point at, so it needs its
--      own record — otherwise the same rejected idea reappears on every page
--      load and the tool becomes noise.
--
--  Run this after 0003_analytics.sql.
-- ============================================================================

create table if not exists public.match_suggestion_dismissals (
  sku              text not null references public.parts (sku) on delete cascade,
  from_branch_id   text not null references public.branches (id) on delete cascade,
  to_branch_id     text not null references public.branches (id) on delete cascade,
  reason           text,
  dismissed_by     text not null,
  dismissed_by_id  uuid references public.profiles (id) on delete set null,
  dismissed_at     timestamptz not null default now(),
  primary key (sku, from_branch_id, to_branch_id),
  constraint dismissal_distinct_branches check (from_branch_id <> to_branch_id)
);

create index if not exists match_suggestion_dismissals_at_idx
  on public.match_suggestion_dismissals (dismissed_at desc);

alter table public.match_suggestion_dismissals enable row level security;

drop policy if exists dismissals_select on public.match_suggestion_dismissals;
create policy dismissals_select on public.match_suggestion_dismissals
  for select to authenticated using (public.is_active_user());

-- Sales may not overrule an operational decision, so dismissing is limited to
-- the two roles that actually move stock.
drop policy if exists dismissals_insert on public.match_suggestion_dismissals;
create policy dismissals_insert on public.match_suggestion_dismissals
  for insert to authenticated
  with check (
    public.is_management()
    or (public.is_warehouse() and dismissed_by_id = auth.uid())
  );

drop policy if exists dismissals_delete on public.match_suggestion_dismissals;
create policy dismissals_delete on public.match_suggestion_dismissals
  for delete to authenticated using (public.is_management());

